-- REVIEW BEFORE RUNNING. Target authorized by owner: hnkplvyegonlhumlejst (Production).
-- Adds only 91 approved A-G mappings. REVIEW, EXCLUDED, and two conditional pajama-set categories are omitted.
begin;
create temp table approved_category_mappings (policy_version text,source_code text,source_category_key text,group_code text,disposition text,category_path text[],source_ids jsonb,source_names jsonb,audience_codes text[],product_count integer,sample_products jsonb,mapping_basis text,notes text[],source_record jsonb) on commit drop;
do $$ begin
 if (select count(*) from approved_category_mappings)<>91 then raise exception 'approved mapping count mismatch'; end if;
 if exists(select 1 from approved_category_mappings a join fitmatch_catalog.source_category_comparison_groups m on m.policy_version=a.policy_version and m.source_code=a.source_code and m.source_category_key=a.source_category_key) then raise exception 'mapping key already exists; no rows applied'; end if;
end $$;
do $$ begin
 if (select count(*) from fitmatch_catalog.source_category_comparison_groups where policy_version='retailer-comparison-groups-v3-seven-20260911' and mapping_basis='RETAILER_API_CATEGORY_AUDIT_APPROVED_20260916')<>91 then raise exception 'post-insert count mismatch'; end if;
end $$;
commit;
select source_code,group_code,count(*)::int as applied_count from fitmatch_catalog.source_category_comparison_groups where policy_version='retailer-comparison-groups-v3-seven-20260911' and mapping_basis='RETAILER_API_CATEGORY_AUDIT_APPROVED_20260916' group by source_code,group_code order by source_code,group_code;
